UPDATE movie_entry SET rewatches = (SELECT json_group_array(json_object('startedAt', NULL, 'finishedAt', value)) FROM (SELECT value FROM json_each(movie_entry.rewatches) ORDER BY value)) WHERE rewatches <> '[]' AND json_type(rewatches, '$[0]') = 'text';
UPDATE season_entry SET rewatches = (SELECT json_group_array(json_object('startedAt', NULL, 'finishedAt', value)) FROM (SELECT value FROM json_each(season_entry.rewatches) ORDER BY value)) WHERE rewatches <> '[]' AND json_type(rewatches, '$[0]') = 'text';
UPDATE videogame_entry SET rewatches = (SELECT json_group_array(json_object('startedAt', NULL, 'finishedAt', value)) FROM (SELECT value FROM json_each(videogame_entry.rewatches) ORDER BY value)) WHERE rewatches <> '[]' AND json_type(rewatches, '$[0]') = 'text';
UPDATE book_entry SET rewatches = (SELECT json_group_array(json_object('startedAt', NULL, 'finishedAt', value)) FROM (SELECT value FROM json_each(book_entry.rewatches) ORDER BY value)) WHERE rewatches <> '[]' AND json_type(rewatches, '$[0]') = 'text';
